def A_lin(state, a, u, p):
    """A of M d/dt(dx) = A dx + B du (columns: states)."""
    _check_params(p, _PARAMS)
    state = _arr(state, 12, "state")
    R = state[0:9].reshape(3, 3)
    Omega_R = state[9:12]
    J = _mat(p["J"])
    rho = _vec(p["\\rho"])
    e3 = _vec(p["e3"])
    g = _scalar(p["g"], "g")
    m = _scalar(p["m"], "m")
    _t0 = _hat(Omega_R)
    out = np.zeros((6, 6))
    out[0:3, 0:3] = _t0 * -1
    out[0:3, 3:6] = np.eye(3)
    out[3:6, 0:3] = _hat(rho) @ _hat(R.T @ e3) * (m * g * -1)
    out[3:6, 3:6] = _hat(J @ Omega_R) + _t0 @ J * -1
    return out


def B_lin(state, a, u, p):
    """B of M d/dt(dx) = A dx + B du (columns: inputs)."""
    _check_params(p, _PARAMS)
    out = np.zeros((6, 3))
    out[3:6, 0:3] = np.eye(3)
