def kinematics(state):
    """Configuration rates: ds/dt, dx/dt, omega x q, R hat(Omega) (row-major)."""
    state = _arr(state, 12, "state")
    R = state[0:9].reshape(3, 3)
    Omega_R = state[9:12]
    _t0 = (R @ _hat(Omega_R)).reshape(9)
    out = np.zeros(9)
    out[0:9] = _t0
    return out
